import React, { FC, useState } from "react";

interface Product {
  id: number;
  name: string;
  price: number;
}

export function CartCheckout(): JSX.Element {
  const [cartItems, setCartItems] = useState<Product[]>([]);
  const [totalPrice, setTotalPrice] = useState<number>(0);

  // Example function to simulate fetching cart items
  const fetchCartItems = async (): Promise<void> => {
    const response = await fetch("https://example.com/api/cart-items");
    const data = await response.json();
    setCartItems(data);
    calculateTotalPrice(data);
  };

  const calculateTotalPrice = (items: Product[]): void => {
    const total = items.reduce((acc, item) => acc + item.price, 0);
    setTotalPrice(total);
  };

  const handleCheckout = async (): Promise<void> => {
    const orderData = { items: cartItems.map(item => ({ id: item.id, quantity: 1 })) };
    const response = await fetch("/api/orders-api/create", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(orderData),
    });

    if (!response.ok) {
      console.error("Failed to create order");
      return;
    }

    const orderResponse = await response.json();
    const chargeData = { orderId: orderResponse.orderId, amount: totalPrice };

    const paymentResponse = await fetch("/api/payment-gateway-adapter/charge", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(chargeData),
    });

    if (!paymentResponse.ok) {
      console.error("Payment failed");
      return;
    }

    alert("Order placed successfully!");
  };

  React.useEffect(() => {
    fetchCartItems();
  }, []);

  return (
    <div>
      <h1>Cart</h1>
      <ul>
        {cartItems.map(item => (
          <li key={item.id}>{item.name} - ${item.price.toFixed(2)}</li>
        ))}
      </ul>
      <p>Total Price: ${totalPrice.toFixed(2)}</p>
      <button onClick={handleCheckout}>Checkout</button>
    </div>
  );
}

