import React, { FC, useEffect, useState } from "react";

interface Transaction {
  id: number;
  amount: number;
  description: string;
  category?: string;
}

export function TransactionList(): JSX.Element {
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  useEffect(() => {
    fetch("/api/categorisation-api/transactions")
      .then(response => response.json())
      .then(data => setTransactions(data));
  }, []);

  const handleCategoryChange = (id: number, category: string) => {
    fetch(`/api/categorisation-api/transactions/${id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ category }),
    }).then(() => {
      setTransactions(prevTransactions => prevTransactions.map(transaction =>
        transaction.id === id ? { ...transaction, category } : transaction
      ));
    });
  };

  return (
    <div>
      <h1>Transaction List</h1>
      <ul>
        {transactions.map(transaction => (
          <li key={transaction.id}>
            {transaction.description}: ${transaction.amount.toFixed(2)}
            {transaction.category ? (<span> - Category: {transaction.category}</span>) : null}
            <input
              type="text"
              placeholder="Enter category"
              onChange={(e) => handleCategoryChange(transaction.id, e.target.value)}
            />
          </li>
        ))}
      </ul>
    </div>
  );
}

